#!/usr/bin/bash
# OldNet themes for Thunderbird (the Mail tab app): one per palette, generated by
# tools/gen-themes.py into /usr/share/oldnet/thunderbird/themes/<id>/manifest.json.
# Each is zipped into an .xpi and installed for every user by a Thunderbird policy;
# Night Market is the default theme.
set -euo pipefail

SRC=/usr/share/oldnet/thunderbird/themes
DEFAULT_THEME=oldnet-nightmarket@themes.oldnet.os

# Thunderbird reads policies from <install dir>/distribution/policies.json.
appini=$(rpm -ql thunderbird | grep -m1 '/application.ini$') \
  || { echo "Thunderbird install dir not found"; exit 1; }
DIST="$(dirname "$appini")/distribution"
mkdir -p "$DIST"

python3 - "$SRC" "$DIST/policies.json" "$DEFAULT_THEME" <<'EOF'
import json, os, sys, zipfile

src, policies_path, default_theme = sys.argv[1:]
themes = sorted(d for d in os.listdir(src) if os.path.isdir(os.path.join(src, d)))
if not themes:
    sys.exit("no Thunderbird themes found in " + src)

settings = {}
for theme_id in themes:
    xpi = os.path.join(os.path.dirname(src), theme_id + ".xpi")
    with zipfile.ZipFile(xpi, "w", zipfile.ZIP_DEFLATED) as z:
        z.write(os.path.join(src, theme_id, "manifest.json"), "manifest.json")
    # normal_installed: present for everyone, users can still switch themes.
    settings[theme_id] = {"installation_mode": "normal_installed", "install_url": "file://" + xpi}
    print("theme", theme_id, "->", xpi)

if default_theme not in settings:
    sys.exit("default theme missing: " + default_theme)

policies = {"policies": {}}
if os.path.exists(policies_path):          # keep anything Fedora or Bazzite ship
    with open(policies_path) as f:
        policies = json.load(f)
p = policies.setdefault("policies", {})
p.setdefault("ExtensionSettings", {}).update(settings)
p.setdefault("Preferences", {})["extensions.activeThemeID"] = {
    "Value": default_theme, "Status": "default"}
with open(policies_path, "w") as f:
    json.dump(policies, f, indent=2)
print("policies:", policies_path)
EOF
